 moveTowards(a,dt,speed){const dx=a.tx-a.x,dy=a.ty-a.y,len=Math.hypot(dx,dy),step=Math.min(len,speed*dt/1000);if(len){a.x+=dx/len*step;a.y+=dy/len*step;}}
 penaltyOutcome(success,kind){if(kind==='save')this.shot.deflect={vx:(this.shot.tx<500?-1:1)*140,vy:-140};this.penaltyState='outcome';this.outcomeUntil=this.clock+1000;this.attempts++;if(success){this.success++;this.correct(40+Math.round((this.variant==='taker'?this.shot.power:1)*10),this.shot.tx,this.shot.ty,null);if(this.variant==='keeper'&&this.responseAt!=null)this.reactions.push(this.responseAt-this.shot.start);this.text(this.variant==='taker'?'GOAL! What a finish!':'SAVED! Safe hands!');this.emit(this.variant==='taker'?'goal':'save');}else{this.miss();this.text(kind==='wide'?'Wide! Keep your aim inside the posts.':this.variant==='taker'?'Saved by the keeper!':'Goal! Try to meet the ball sooner.');this.emit('crowd');}this.shotLog.push({success,kind,flight:Math.round(this.shot.flight),target:{x:this.shot.tx,y:this.shot.ty},power:this.shot.power,curl:this.shot.curl});}
 updateKeeper(dt){if(this.penaltyState==='waiting'&&this.variant!=='taker'&&this.clock>=this.nextShotAt)this.launchPenalty();this.moveTowards(this.glove,dt,this.cfg.keeperSpeed);if(this.penaltyState==='flight'){let b=this.shot,z=clamp((this.clock-b.start)/b.flight,0,1);b.z=z;b.x=500+(b.tx-500)*z+Math.sin(z*Math.PI)*b.curl*140;b.y=575+(b.ty-575)*z-Math.sin(z*Math.PI)*45;b.r=23-z*9;if(this.variant==='taker'&&this.clock>=this.ai.reactAt)this.moveTowards(this.ai,dt,this.ai.speed);if(z>=1){const g=this.goal(),wide=b.tx<g.x+15||b.tx>g.x+g.w-15||b.ty<g.y+15||b.ty>g.y+g.h-15,keeper=this.variant==='taker'?this.ai:this.glove,range=[76,68,60,53,47][this.difficulty-1],saved=!wide&&Math.hypot(keeper.x-b.tx,keeper.y-b.ty)<=range;this.penaltyOutcome(this.variant==='taker'?!wide&&!saved:saved,wide?'wide':saved?'save':'goal');}}
 if(this.penaltyState==='outcome'&&this.shot?.deflect){const b=this.shot,v=b.deflect;v.vy+=450*dt/1000;b.x+=v.vx*dt/1000;b.y+=v.vy*dt/1000;if(b.y>520){b.y=520;v.vy*=-.45;v.vx*=.8;}}if(this.penaltyState==='outcome'&&this.clock>=this.outcomeUntil){if(this.attempts>=(this.attemptLimit||5)){this.done=true;return;}this.penaltyState='waiting';this.nextShotAt=this.clock+this.rand(700,1600)+(this.difficulty>=3&&this.rng()<.3?800:0);this.shot=null;this.ai={...this.ai,x:500,y:390,tx:500,ty:390};this.glove.tx=500;this.glove.ty=395;}}
 initDig(saved){if(saved){this.restoreDig(saved);return;}this.depth=0;this.cleared=0;this.discoveries=[];this.tool='shovel';this.scans=0;this.scannerUntil=0;this.digCooldown=new Map();this.layers=Array.from({length:3},(_,depth)=>this.makeLayer(depth));this.cells=this.layers[0];this.stats={cleared:0};}
 makeLayer(depth){return Array.from({length:80},(_,i)=>{let row=Math.floor(i/10),max=clamp(1+Math.floor(row/2)+depth+Math.floor((this.difficulty-1)/2),0,7);let material=Math.floor(this.rand(Math.max(0,max-2),max+1));if(depth===0&&row<2)material=i===0?0:Math.min(material,1);const hp=Math.ceil(MATERIALS[material].hp*this.cfg.digFactor);let treasure=(i%13===7||i===(depth===2?77:64))?(i===77?6:(Math.floor(this.rand(0,5+depth)))):null;return{material,hp,maxHp:hp,treasure,cleared:false,found:false};});}
 unlockedTool(id){let t=TOOLS.find(t=>t.id===id);return !!t&&this.cleared>=t.unlock;}
